parameters.jsCode:
// Get input data
const input = $input.first().json;

// Parse participants into array
const participantsRaw = input.participants || "";
const participantsList = participantsRaw
  .split('\n')
  .filter(line => line.trim().length > 0)
  .map(line => {
    // Expected format: "Name - email@domain.com"
    const parts = line.split('-').map(p => p.trim());
    if (parts.length >= 2) {
      return {
        name: parts[0],
        email: parts[1]
      };
    }
    return null;
  })
  .filter(p => p !== null);

// Validate we have at least one participant
if (participantsList.length === 0) {
  throw new Error("No valid participants found. Format: Name - email@domain.com");
}

// Validate meeting notes length
const notes = input.meetingNotes || "";
if (notes.length < 100) {
  throw new Error("Meeting notes must be at least 100 characters");
}

// Parse reminder preferences
const reminderPrefs = input.reminderPreferences || [];
const reminders = {
  twoDaysBefore: reminderPrefs.includes('2days'),
  oneDayBefore: reminderPrefs.includes('1day'),
  onDeadline: reminderPrefs.includes('deadline'),
  oneDayAfter: reminderPrefs.includes('overdue')
};

// Return cleaned data
return [{
  json: {
    meetingTitle: input.meetingTitle,
    meetingDate: input.meetingDate,
    meetingType: input.meetingType,
    teamDepartment: input.teamDepartment || "Not specified",
    meetingLead: input.meetingLead,
    leadEmail: input.leadEmail,
    participants: participantsList,
    participantCount: participantsList.length,
    meetingNotes: notes,
    recordingLink: input.recordingLink || "",
    additionalContext: input.additionalContext || "",
    reminderSettings: reminders,
    submittedAt: input.timestamp || new Date().toISOString()
  }
}];

const data = $input.first().json;

// Generate unique meeting ID
const timestamp = Date.now();
const randomStr = Math.random().toString(36).substring(2, 8);
const meetingId = `MTG-${timestamp}-${randomStr}`;

return [{
  json: {
    ...data,
    meetingId: meetingId
  }
}];

parameters.text:
=Analyze this meeting and extract structured information.

MEETING DETAILS:
Title: {{ $json['Meeting Title'] }}
Date: {{ $json['Meeting Date'] }}
Type: {{ $json['Meeting Type'] }}
Team: {{ $json['Team/Department'] }}
Lead: {{ $json['Lead Email'] }}

PARTICIPANTS:
{{ $json.Participants }}

ADDITIONAL CONTEXT:
{{ $('Parse & Validate Input').item.json.additionalContext }}

MEETING NOTES:
{{ $json['Raw Notes'] }}

---
EXTRACT THE FOLLOWING (respond ONLY in valid JSON format):

{
  "meetingSummary": "2-3 sentence summary of the meeting's purpose and outcomes",
  "decisions": [
    {
      "decision": "Clear statement of what was decided",
      "impact": "Who/what this affects"
    }
  ],
  "actionItems": [
    {
      "task": "Clear, specific description of the task",
      "owner": "Exact name of person responsible (must match participant list) or 'UNASSIGNED'",
      "deadline": "YYYY-MM-DD format or 'NO_DEADLINE' or 'ASAP'",
      "priority": "HIGH or MEDIUM or LOW",
      "context": "Why this task matters or any dependencies"
    }
  ],
  "unclearItems": [
    "Any discussions that seemed important but had no clear owner or deadline"
  ],
  "nextMeetingNeeded": true or false,
  "blockers": [
    "Any identified blockers or risks mentioned"
  ]
}

IMPORTANT RULES:
1. Owner names MUST exactly match names from the participant list above
2. If no clear owner, use 'UNASSIGNED'
3. If no deadline mentioned, use 'NO_DEADLINE'
4. Extract ALL action items, even small ones
5. Decisions are agreements/conclusions, not tasks
6. Return ONLY the JSON, no other text
7. Ensure valid JSON syntax

