parameters.jsCode:
const data = $input.first().json.output;
const tasks = data.actionItems || [];
const meetingId = data.meetingId;

// Convert each task to sheet row format
const taskRows = tasks.map((task, index) => {
  const taskId = `${meetingId}-TASK-${index + 1}`;

  return {
    json: {
      taskId: taskId,
      meetingId: meetingId,
      taskDescription: task.task,
      ownerName: task.owner,
      ownerEmail: findOwnerEmail(task.owner, data.participants),
      deadline: task.deadline,
      status: "Pending",
      priority: task.priority || "MEDIUM",
      createdDate: new Date().toISOString().split('T')[0],
      lastReminderSent: "",
      completionDate: ""
    }
  };
});

// Helper function to find email
function findOwnerEmail(ownerName, participants) {
  if (ownerName === "UNASSIGNED") return "";

  const participant = participants.find(p => 
    p.name.toLowerCase().includes(ownerName.toLowerCase()) ||
    ownerName.toLowerCase().includes(p.name.toLowerCase())
  );

  return participant ? participant.email : "";
}

return taskRows;

// Get data from Parse AI Response node
const data = $('AI Extraction Node').first().json.output;
const decisions = data.decisions || [];
const meetingId = data.meetingId;

// Convert each decision to sheet row
const decisionRows = decisions.map((decision, index) => {
  const decisionId = `${meetingId}-DEC-${index + 1}`;

  return {
    json: {
      decisionId: decisionId,
      meetingId: meetingId,
      decisionDescription: decision.decision,
      impact: decision.impact || "Not specified",
      recordedDate: new Date().toISOString().split('T')[0]
    }
  };
});

return decisionRows.length > 0 ? decisionRows : [{ json: { skip: true } }];

// Get parsed data
const data = $('AI Extraction Node').first().json.output;
const participants = data.participants || [];
const actionItems = data.actionItems || [];
const decisions = data.decisions || [];

// Group tasks by participant
const participantTasks = {};

participants.forEach(participant => {
  participantTasks[participant.email] = {
    name: participant.name,
    email: participant.email,
    tasks: []
  };
});

// Assign tasks to participants
actionItems.forEach(task => {
  const ownerName = task.owner;

  if (ownerName === "UNASSIGNED") return;

  // Find matching participant
  const participant = participants.find(p => 
    p.name.toLowerCase().includes(ownerName.toLowerCase()) ||
    ownerName.toLowerCase().includes(p.name.toLowerCase())
  );

  if (participant && participantTasks[participant.email]) {
    participantTasks[participant.email].tasks.push(task);
  }
});

// Convert to array for iteration
const results = Object.values(participantTasks)
  .filter(p => p.tasks.length > 0)
  .map(participant => ({
    json: {
      meetingId: data.meetingId,
      meetingTitle: data.meetingTitle,
      meetingDate: data.meetingDate,
      meetingSummary: data.meetingSummary,
      participantName: participant.name,
      participantEmail: participant.email,
      tasks: participant.tasks,
      taskCount: participant.tasks.length,
      decisions: decisions,
      blockers: data.blockers || [],
      meetingLead: data.meetingLead,
      leadEmail: data.leadEmail
    }
  }));

return results;

const allTasks = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

const tasksNeedingReminders = [];

allTasks.forEach(item => {
  const task = item.json;

  // Skip if not pending
  if (task.Status !== "Pending") return;

  // Skip if no valid email
  if (!task["Owner Email"] || task["Owner Email"].trim() === "") return;

  // Skip if deadline is not a valid date
  const deadline = task.Deadline;
  if (!deadline || deadline === "NO_DEADLINE" || deadline === "ASAP") return;

  // Parse deadline
  const deadlineDate = new Date(deadline);
  if (isNaN(deadlineDate)) return;

  deadlineDate.setHours(0, 0, 0, 0);

  // Calculate days until deadline
  const daysUntil = Math.floor((deadlineDate - today) / (1000 * 60 * 60 * 24));

  // Check if reminder needed
  let reminderType = null;

  if (daysUntil === 2) {
    reminderType = "2_DAYS_BEFORE";
  } else if (daysUntil === 1) {
    reminderType = "1_DAY_BEFORE";
  } else if (daysUntil === 0) {
    reminderType = "DUE_TODAY";
  } else if (daysUntil === -1) {
    reminderType = "1_DAY_OVERDUE";
  }

  if (reminderType) {
    tasksNeedingReminders.push({
      json: {
        taskId: task["Task ID"],
        meetingId: task["Meeting ID"],
        taskDescription: task["Task Description"],
        ownerName: task["Owner Name"],
        ownerEmail: task["Owner Email"],
        deadline: deadline,
        priority: task.Priority,
        reminderType: reminderType,
        daysUntil: daysUntil
      }
    });
  }
});

return tasksNeedingReminders.length > 0 ? tasksNeedingReminders : [];
